"use client"

import { useEffect, useRef, useState } from "react"

import "./tybow-motion.css"

import { ArrowButton } from "@/components/tybow/arrow-button"
import { MediaStack } from "@/components/tybow/flush-photo"
import { cn } from "@/lib/utils"

export type EditorialPhoto = {
  src?: string
  alt: string
  name?: string
  tag?: string
}

export type EditorialBlockProps = {
  id?: string
  eyebrow?: string
  title: string
  copy: string
  coda?: string
  pointsTitle?: string
  points?: string[]
  photo?: { src?: string; alt: string }
  photos?: EditorialPhoto[]
  cta?: { href: string; label: string }
  note?: string
}

export function EditorialBlock({
  id,
  eyebrow,
  title,
  copy,
  coda,
  pointsTitle,
  points,
  photo,
  photos,
  cta,
  note,
}: EditorialBlockProps) {
  const frames: EditorialPhoto[] = photos?.length
    ? photos
    : photo
      ? [photo]
      : []
  const [on, setOn] = useState(0)
  const [restartKey, setRestartKey] = useState(0)
  const rootRef = useRef<HTMLDivElement>(null)
  const specRef = useRef<HTMLDivElement>(null)
  const timerRef = useRef<number | null>(null)
  const current = frames[on]

  function go(n: number) {
    if (!frames.length) return
    setOn((n + frames.length) % frames.length)
    setRestartKey((key) => key + 1)
  }

  useEffect(() => {
    const spec = specRef.current
    if (!spec) return
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    if (reduce) {
      spec.classList.add("is-inview")
      return
    }
    const mark = () => spec.classList.add("is-inview")
    const due = () => spec.getBoundingClientRect().top < window.innerHeight * 0.88
    if (!("IntersectionObserver" in window)) {
      mark()
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting && !due()) return
          mark()
          io.disconnect()
        })
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.12 },
    )
    const onScroll = () => {
      if (!due()) return
      mark()
      io.disconnect()
      window.removeEventListener("scroll", onScroll)
    }
    if (due() && spec.getBoundingClientRect().bottom > 0) {
      requestAnimationFrame(() => requestAnimationFrame(mark))
    } else {
      io.observe(spec)
      window.addEventListener("scroll", onScroll, { passive: true })
    }
    return () => {
      io.disconnect()
      window.removeEventListener("scroll", onScroll)
    }
  }, [])

  useEffect(() => {
    const framesCount = frames.length
    if (framesCount < 2) return
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const root = rootRef.current

    function stop() {
      if (timerRef.current) window.clearInterval(timerRef.current)
      timerRef.current = null
    }

    function restart() {
      stop()
      if (reduce) return
      timerRef.current = window.setInterval(() => {
        setOn((i) => (i + 1) % framesCount)
      }, 5200)
    }

    restart()
    if (!root) return () => stop()

    const onEnter = () => stop()
    const onLeave = () => restart()
    const onFocusIn = () => stop()
    const onFocusOut = (event: FocusEvent) => {
      if (!root.contains(event.relatedTarget as Node | null)) restart()
    }
    root.addEventListener("mouseenter", onEnter)
    root.addEventListener("mouseleave", onLeave)
    root.addEventListener("focusin", onFocusIn)
    root.addEventListener("focusout", onFocusOut)
    return () => {
      stop()
      root.removeEventListener("mouseenter", onEnter)
      root.removeEventListener("mouseleave", onLeave)
      root.removeEventListener("focusin", onFocusIn)
      root.removeEventListener("focusout", onFocusOut)
    }
  }, [frames.length, restartKey])

  return (
    <section id={id} className="bg-background">
      <div
        className={cn(
          "grid items-start gap-10 py-section pl-[7vw]",
          frames.length
            ? "lg:grid-cols-[minmax(0,clamp(23rem,38vw,36rem))_minmax(0,1fr)] lg:grid-rows-[auto_1fr]"
            : "max-w-[46rem] pr-[7vw]",
        )}
      >
        <div className="max-w-xl pr-6">
          {eyebrow ? (
            <p className="text-[0.7rem] font-medium tracking-[0.26em] text-primary uppercase">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-4 max-w-[18ch] font-display text-[length:clamp(1.85rem,3.2vw,3rem)] font-light tracking-[0.055em] text-foreground uppercase">
            {title}
          </h2>
          <p className="mt-5 text-[1.0625rem] leading-[1.72] text-pretty text-foreground">
            {copy}
          </p>
          {coda ? (
            <p className="mt-5 font-display text-xl font-medium text-balance text-foreground">
              {coda}
            </p>
          ) : null}
        </div>
        {frames.length ? (
          <div
            ref={rootRef}
            className="relative min-h-[22rem] w-full overflow-hidden bg-muted lg:row-span-2 lg:min-h-[36rem]"
          >
            <MediaStack
              frames={frames}
              on={on}
              slideClassName="tybow-overview-slide"
              className="absolute inset-0 size-full"
            />
            {current?.name ? (
              <div className="pointer-events-none absolute inset-x-0 bottom-0 z-[2] bg-gradient-to-t from-foreground/70 to-transparent px-5 pt-10 pb-9 text-center text-primary-foreground">
                <p className="font-display text-[length:clamp(1.35rem,2.2vw,1.85rem)] font-medium tracking-[-0.02em]">
                  {current.name}
                </p>
                {current.tag ? (
                  <p className="mt-1 text-[0.7rem] font-semibold tracking-[0.14em] uppercase">
                    {current.tag}
                  </p>
                ) : null}
              </div>
            ) : null}
            {frames.length > 1 ? (
              <>
                <button
                  type="button"
                  aria-label="Previous image"
                  className="absolute top-1/2 left-3 z-[3] grid size-[2.4rem] -translate-y-1/2 place-items-center border border-primary-foreground/45 bg-foreground/45 text-[1.35rem] text-primary-foreground"
                  onClick={() => go(on - 1)}
                >
                  ‹
                </button>
                <button
                  type="button"
                  aria-label="Next image"
                  className="absolute top-1/2 right-3 z-[3] grid size-[2.4rem] -translate-y-1/2 place-items-center border border-primary-foreground/45 bg-foreground/45 text-[1.35rem] text-primary-foreground"
                  onClick={() => go(on + 1)}
                >
                  ›
                </button>
                <div className="absolute bottom-2 left-1/2 z-[3] flex -translate-x-1/2 gap-1">
                  {frames.map((frame, index) => (
                    <button
                      key={`${frame.alt}-${index}`}
                      type="button"
                      aria-label={`Show image ${index + 1}`}
                      className={cn(
                        "size-[0.45rem]",
                        index === on
                          ? "bg-primary-foreground"
                          : "bg-primary-foreground/40",
                      )}
                      onClick={() => go(index)}
                    />
                  ))}
                </div>
              </>
            ) : null}
          </div>
        ) : null}
        {points && points.length > 0 ? (
          <div ref={specRef} className="tybow-spec max-w-xl pr-6 lg:col-start-1">
            {pointsTitle ? (
              <p className="border-b border-border pb-3 text-[0.6875rem] font-medium tracking-[0.2em] text-muted-foreground uppercase">
                {pointsTitle}
              </p>
            ) : null}
            <ul>
              {points.map((point) => (
                <li
                  key={point}
                  className="tybow-spec-line relative grid grid-cols-[1rem_minmax(0,1fr)] items-center gap-3 py-3 text-foreground"
                >
                  <span
                    aria-hidden="true"
                    className="tybow-spec-tick size-4 bg-primary [mask:url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22><path fill=%22white%22 d=%22M9.2 16.6 4.8 12.2l1.4-1.4 3 3 8.2-8.2 1.4 1.4z%22/></svg>')_center_/_contain_no-repeat]"
                  />
                  {point}
                </li>
              ))}
            </ul>
            {cta || note ? (
              <div className="mt-8 flex flex-wrap items-center gap-x-7 gap-y-4">
                {cta ? (
                  <ArrowButton href={cta.href} variant="inverse">
                    {cta.label}
                  </ArrowButton>
                ) : null}
                {note ? (
                  <p className="max-w-[17rem] text-[0.8125rem] leading-5 text-muted-foreground">
                    {note}
                  </p>
                ) : null}
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </section>
  )
}

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"

function ArrowIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M3 8h10M9 4l4 4-4 4"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="square"
      />
    </svg>
  )
}

export type ArrowButtonProps = {
  variant?: "cream" | "inverse" | "ghost"
  href?: string
  className?: string
  children: ReactNode
} & Omit<ComponentProps<"button">, "className">

export function ArrowButton({
  variant = "cream",
  href,
  className,
  children,
  type = "button",
  ...props
}: ArrowButtonProps) {
  const classes = cn(
    "inline-flex min-h-[3.25rem] items-center gap-3 pr-1.5 pl-5 font-sans text-[0.92rem] font-semibold tracking-[0.04em] uppercase",
    variant === "cream" &&
      "bg-primary-foreground text-foreground shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_32%,transparent)] hover:bg-white",
    variant === "inverse" && "bg-primary text-primary-foreground hover:brightness-90",
    variant === "ghost" &&
      "min-h-[3.25rem] border-[1.5px] border-primary-foreground bg-foreground/60 px-5 text-primary-foreground hover:border-white hover:bg-foreground/80",
    className,
  )

  const iconWrap =
    variant === "ghost" ? null : (
      <span
        className={cn(
          "grid size-9 place-items-center",
          variant === "cream" && "bg-primary text-primary-foreground",
          variant === "inverse" && "bg-primary-foreground text-primary",
        )}
      >
        <ArrowIcon />
      </span>
    )

  const inner = (
    <>
      {children}
      {iconWrap}
    </>
  )

  if (href) {
    return (
      <a href={href} className={classes}>
        {inner}
      </a>
    )
  }

  return (
    <button type={type} className={classes} {...props}>
      {inner}
    </button>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export type MediaFrame = { src?: string; alt: string }

export function MediaStack({
  frames,
  on,
  slideClassName,
  className,
  objectPosition,
}: {
  frames: MediaFrame[]
  on: number
  slideClassName: string
  className?: string
  objectPosition?: string
}) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {frames.map((frame, index) =>
        frame.src ? (
          // Parent owns crop. Animation classes must land on the img.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={`${frame.src}-${index}`}
            src={frame.src}
            alt={index === on ? frame.alt : ""}
            decoding="async"
            className={cn(slideClassName, index === on && "is-on")}
            style={objectPosition ? { objectPosition } : undefined}
          />
        ) : (
          <div
            key={`${frame.alt}-${index}`}
            className={cn(
              slideClassName,
              index === on && "is-on",
              "flex items-center justify-center bg-muted",
            )}
            role="img"
            aria-label={frame.alt}
          />
        ),
      )}
    </div>
  )
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}

/* Motion ported from The Pines: wh-pines.css + wh-pe-brand.css.
   Token-only. Values (timings, easings, travel) stay literal. */

@keyframes tybow-pull {
  to {
    transform: none;
    opacity: 1;
  }
}

.tybow-pull {
  display: inline-block;
  transform: translateY(0.42em);
  opacity: 0;
  animation: tybow-pull 0.72s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(var(--i, 0) * 90ms + 80ms);
}

.tybow-pull-late {
  transform: translateY(0.8rem);
  opacity: 0;
  animation: tybow-pull 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Ken Burns lives on the IMG, not a wrapper. */
.tybow-hero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 50% 52%;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 7s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.tybow-hero-slide.is-on {
  opacity: 1;
  transform: scale(1);
}

.tybow-look-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-look-slide.is-on {
  opacity: 1;
}

.tybow-overview-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-overview-slide.is-on {
  opacity: 1;
  z-index: 1;
}

.tybow-gallery {
  display: flex;
  flex-direction: row;
  gap: 1px;
  width: 100%;
  height: min(56vh, 32rem);
  min-height: 22rem;
  overflow: hidden;
  background: var(--foreground);
}

.tybow-gallery-item {
  position: relative;
  overflow: hidden;
  flex: 0.5 1 2.55rem;
  min-width: 2.45rem;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--foreground);
  cursor: pointer;
  text-align: left;
  line-height: 0;
  transition: flex-grow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-gallery-item.is-active {
  flex-grow: 16;
}

.tybow-gallery-item img,
.tybow-gallery-item .tybow-gallery-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}

.tybow-gallery-item::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to right,
    color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
    color-mix(in oklch, var(--foreground) 62%, transparent) 55%,
    color-mix(in oklch, var(--foreground) 28%, transparent) 100%
  );
  opacity: 1;
  transition: opacity 0.3s ease;
}

.tybow-gallery-item.is-active::after {
  opacity: 0;
}

.tybow-gallery-spine {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 1;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  padding: 1.05rem 0.55rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  text-shadow: 0 1px 12px color-mix(in oklch, var(--foreground) 70%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-spine {
  opacity: 0;
}

.tybow-gallery-cap {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  padding: 2.6rem 1.2rem 1.05rem;
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--foreground) 70%, transparent),
    transparent
  );
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  pointer-events: none;
  opacity: 0;
  transform: translateY(0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-cap {
  opacity: 1;
  transform: none;
}

.tybow-deck-card-body,
.tybow-deck-card::after {
  transition:
    opacity 420ms ease,
    transform 420ms ease;
}

.tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
  opacity: 0.55;
  transform: translateY(10px);
}

.tybow-spec-line {
  --pin-line-delay: 0ms;
}

.tybow-spec-line::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 1px;
  background: var(--border);
}

@media (prefers-reduced-motion: no-preference) {
  .tybow-spec .tybow-spec-line::after {
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 620ms cubic-bezier(0.23, 1, 0.32, 1)
      var(--pin-line-delay, 0ms);
  }

  .tybow-spec .tybow-spec-tick {
    opacity: 0;
    transform: translateX(-5px);
    transition:
      opacity 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms),
      transform 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms);
  }

  .tybow-spec.is-inview .tybow-spec-line::after {
    transform: scaleX(1);
  }

  .tybow-spec.is-inview .tybow-spec-tick {
    opacity: 1;
    transform: none;
  }

  .tybow-spec-line:nth-child(1) {
    --pin-line-delay: 300ms;
  }
  .tybow-spec-line:nth-child(2) {
    --pin-line-delay: 375ms;
  }
  .tybow-spec-line:nth-child(3) {
    --pin-line-delay: 450ms;
  }
  .tybow-spec-line:nth-child(4) {
    --pin-line-delay: 525ms;
  }
  .tybow-spec-line:nth-child(5) {
    --pin-line-delay: 600ms;
  }
  .tybow-spec-line:nth-child(6) {
    --pin-line-delay: 675ms;
  }
}

@media (max-width: 800px) {
  .tybow-gallery {
    height: auto;
    min-height: 0;
    flex-direction: column;
  }

  .tybow-gallery-item {
    flex: 0 0 2.65rem;
    width: 100%;
    min-width: 0;
    height: 2.65rem;
    transition:
      height 0.4s cubic-bezier(0.22, 1, 0.36, 1),
      flex-basis 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .tybow-gallery-item.is-active {
    flex: 0 0 22rem;
    height: 22rem;
  }

  .tybow-gallery-item::after {
    background: linear-gradient(
      to top,
      color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
      color-mix(in oklch, var(--foreground) 45%, transparent) 70%,
      transparent 100%
    );
  }

  .tybow-gallery-spine {
    writing-mode: horizontal-tb;
    transform: none;
    inset: auto auto 0.7rem 0.9rem;
    padding: 0;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
  }
}

@media (max-width: 959px) {
  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tybow-pull,
  .tybow-pull-late {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .tybow-hero-slide,
  .tybow-hero-slide.is-on,
  .tybow-look-slide,
  .tybow-overview-slide,
  .tybow-gallery-item,
  .tybow-gallery-item::after,
  .tybow-gallery-spine,
  .tybow-gallery-cap,
  .tybow-deck-card-body,
  .tybow-deck-card::after {
    transition: none;
    transform: none;
  }

  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}
